CREATE TABLE "production"."auth_identity" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "production"."auth_identity_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer NOT NULL,
	"provider" text NOT NULL,
	"subject" text NOT NULL,
	"email_at_link" text,
	"origin" text NOT NULL,
	"linked_at" text DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') NOT NULL,
	"last_used_at" text,
	CONSTRAINT "auth_identity_provider_check" CHECK ("production"."auth_identity"."provider" in ('google', 'linkedin')),
	CONSTRAINT "auth_identity_origin_check" CHECK ("production"."auth_identity"."origin" in ('automatic', 'manual'))
);
