CREATE TABLE "production"."auth_signup" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "production"."auth_signup_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"kind" text NOT NULL,
	"token_hash" text NOT NULL,
	"email" text NOT NULL,
	"locale" text NOT NULL,
	"role" text,
	"name" text,
	"headline" text,
	"cv_text" text,
	"password_hash" text,
	"provider" text,
	"subject" text,
	"code_hash" text,
	"code_attempts" integer DEFAULT 0 NOT NULL,
	"code_sent_at" text,
	"ip_hmac" text NOT NULL,
	"terms_version" text,
	"privacy_version" text,
	"created_at" text DEFAULT to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') NOT NULL,
	"expires_at" text NOT NULL,
	"completed_at" text,
	"user_id" integer,
	CONSTRAINT "auth_signup_kind_check" CHECK ("production"."auth_signup"."kind" in ('manual', 'social')),
	CONSTRAINT "auth_signup_role_check" CHECK ("production"."auth_signup"."role" is null or "production"."auth_signup"."role" in ('candidate', 'recruiter')),
	CONSTRAINT "auth_signup_provider_check" CHECK ("production"."auth_signup"."provider" is null or "production"."auth_signup"."provider" in ('google', 'linkedin'))
);
